from typing import Any

import pytest
from concurrent.futures import ThreadPoolExecutor


def parity(x: int) -> int:
    return x % 2


def parities(xs: list[int]) -> list[int]:
    """Return the parity (0 or 1) of each element of xs, computed in
    parallel with a thread pool. The result is in input order, regardless
    of the number of workers or task completion order."""
    with ThreadPoolExecutor() as pool:
        return list(pool.map(parity, xs))


def test_parities_basic() -> None:
    assert parities([1, 2, 3, 4]) == [1, 0, 1, 0]


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_negative() -> None:
    assert parities([-1, -2, -3, 0]) == [1, 0, 1, 0]


def test_parities_large_ints() -> None:
    assert parities([10**30, 10**30 + 1]) == [0, 1]


def test_parities_order_large_input() -> None:
    xs = list(range(-500, 500))
    assert parities(xs) == [parity(x) for x in xs]


def test_parities_does_not_mutate_input() -> None:
    xs = [5, 6, 7]
    parities(xs)
    assert xs == [5, 6, 7]


def test_parities_uses_thread_pool(monkeypatch: pytest.MonkeyPatch) -> None:
    used: list[bool] = []
    original: Any = ThreadPoolExecutor.__init__

    def spy(self: ThreadPoolExecutor, *args: Any, **kwargs: Any) -> None:
        used.append(True)
        original(self, *args, **kwargs)

    monkeypatch.setattr(ThreadPoolExecutor, "__init__", spy)
    assert parities([1, 2, 3]) == [1, 0, 1]
    assert used

